# ── DB ─────────────────────────────────────────────────────
CONN_STR = (
    "DRIVER={ODBC Driver 17 for SQL Server};"
    "SERVER=localhost;DATABASE=KingsSchoolEgypt;"
    "UID=sa;PWD=sa123;TrustServerCertificate=yes;"
    "Connection Timeout=5;"
)
def get_conn(): 
    return pyodbc.connect(CONN_STR)

def qy(sql, p=()):
    try:
        with get_conn() as c:
            cur = c.cursor(); cur.execute(sql, p)
            return [tuple(r) for r in cur.fetchall()]
    except pyodbc.Error as e:
        return []

def ex(sql, p=()):
    try:
        with get_conn() as c:
            cur = c.cursor(); cur.execute(sql, p); c.commit()
    except pyodbc.Error as e:
        raise Exception(f"Database error: {str(e)[:120]}")

# ── EGYPT TAX CALCULATION ──────────────────────────────────
SI_CAP_SALARY   = 16700   # EGP — SI calculated on max 16,700 of basic
SI_RATE         = 0.11    # 11% employee share
PERSONAL_EXEMPTION_MONTHLY = 20000 / 12  # 1,666.67/month

EGYPT_TAX_BRACKETS = [
    (0,        40000,   0.000),
    (40000,    55000,   0.100),
    (55000,    70000,   0.150),
    (70000,    200000,  0.200),
    (200000,   400000,  0.225),
    (400000,   1200000, 0.250),
    (1200000,  float('inf'), 0.275),
]

def calc_egypt_tax(monthly_gross, basic_salary,
                   absences=0, lateness=0, sick=0, sanctions=0, other_ded=0):
    """
    Egypt Income Tax — Verified formula:

    Step 1: Net before tax = Gross - (Absences + Lateness + Sick + Sanctions + Other)
    Step 2: SI = min(Basic, 16,700) × 11%  (used ONLY for tax calc, not deducted from salary)
    Step 3: Net for tax = Net before tax - (20,000÷12) - SI
    Step 4: Annual taxable = Net for tax × 12
    Step 5: Apply brackets → Annual tax ÷ 12 = Monthly tax
    Step 6: Net after tax = Net before tax - Monthly tax  (SI NOT deducted from salary)

    Verified:
      Basic=40,000, Gross=45,000 → tax=7,981.17, net=35,863.83 ✓
      Basic=12,000, Gross=17,000 → tax=1,717.50, net=14,127.50 ✓
    """
    deductables = absences + lateness + sick + sanctions + other_ded
    net_before_tax = monthly_gross - deductables

    si_base = min(basic_salary, SI_CAP_SALARY)
    si_monthly = si_base * SI_RATE

    net_for_tax = net_before_tax - PERSONAL_EXEMPTION_MONTHLY - si_monthly
    net_for_tax = max(0, net_for_tax)

    annual_taxable = net_for_tax * 12
    annual_tax = 0.0
    breakdown = []
    for low, high, rate in EGYPT_TAX_BRACKETS:
        if annual_taxable <= low: break
        portion = min(annual_taxable, high) - low
        tax_on_bracket = portion * rate
        annual_tax += tax_on_bracket
        if portion > 0:
            breakdown.append((low, min(annual_taxable, high), rate, tax_on_bracket))

    monthly_tax = annual_tax / 12
    return monthly_tax, annual_tax, si_monthly, net_before_tax, breakdown

