def L(p, text, color=None, fk='body', **kw):
    C = T()
    return ctk.CTkLabel(p, text=text, text_color=color or C['text'], font=F[fk], **kw)

def caps_lbl(p, text):
    C = T()
    return ctk.CTkLabel(p, text=text.upper(), text_color=C['text4'], font=F['caps'])

def inp(p, placeholder='', w=320, show=None):
    C = T()
    kw = dict(placeholder_text=placeholder, width=w, height=38,
              fg_color=C['surface2'], border_color=C['border'],
              text_color=C['text'], placeholder_text_color=C['text4'],
              font=F['body'], corner_radius=6, border_width=1)
    if show: kw['show'] = show
    return ctk.CTkEntry(p, **kw)

def date_inp(p, w=320):
    """Date entry — enforces YYYY-MM-DD format with live validation."""
    C = T()
    var = ctk.StringVar()
    frame = ctk.CTkFrame(p, fg_color='transparent'); frame.pack_configure = frame.pack
    entry = ctk.CTkEntry(frame, textvariable=var, placeholder_text='YYYY-MM-DD',
                         width=w, height=38, fg_color=C['surface2'],
                         border_color=C['border'], text_color=C['text'],
                         placeholder_text_color=C['text4'],
                         font=F['body'], corner_radius=6, border_width=1)
    err_lbl = ctk.CTkLabel(frame, text='', text_color='#E87060',
                           font=F['tiny'])

    def validate(*_):
        v = var.get()
        if not v:
            entry.configure(border_color=C['border']); err_lbl.configure(text=''); return
        import re
        if re.match(r'^\d{4}-\d{2}-\d{2}$', v):
            try:
                datetime.strptime(v, '%Y-%m-%d')
                entry.configure(border_color='#4ECCA3'); err_lbl.configure(text='✓', text_color='#4ECCA3')
                return
            except: pass
        entry.configure(border_color='#E87060')
        err_lbl.configure(text='⚠ Use YYYY-MM-DD  e.g. 2024-01-31', text_color='#E87060')

    var.trace_add('write', validate)
    entry.pack(side='left')
    err_lbl.pack(side='left', padx=8)
    # expose get/insert/configure so it works like a normal entry
    entry.get = lambda: var.get()
    entry.insert = lambda idx, val: var.set(val)
    entry._frame = frame
    return entry

def num_inp(p, w=320, placeholder='0.00'):
    """Number-only entry — rejects non-numeric input."""
    C = T()
    var = ctk.StringVar()
    entry = ctk.CTkEntry(p, textvariable=var, placeholder_text=placeholder,
                         width=w, height=38, fg_color=C['surface2'],
                         border_color=C['border'], text_color=C['text'],
                         placeholder_text_color=C['text4'],
                         font=F['body'], corner_radius=6, border_width=1)
    def validate(*_):
        v = var.get()
        if v == '' or v == '-': return
        # allow digits and one decimal point
        clean = ''.join(c for c in v if c.isdigit() or c == '.')
        if clean.count('.') > 1: clean = clean[:clean.rfind('.')]
        if clean != v: var.set(clean)
    var.trace_add('write', validate)
    return entry

def dropdown(p, values, w=320, var=None):
    """Strict dropdown — user MUST pick from list, cannot type freely."""
    C = T()
    v = var or ctk.StringVar(value=values[0] if values else '')
    cb = ctk.CTkComboBox(p, values=values, variable=v, width=w, height=38,
                         fg_color=C['surface2'], border_color=C['border'],
                         button_color=C['gold'], button_hover_color=C['gold2'],
                         text_color=C['text'], font=F['body'], corner_radius=6,
                         dropdown_fg_color=C['surface2'], dropdown_text_color=C['text'],
                         state='readonly')   # ← prevents typing
    return cb, v

def editable_dropdown(p, values, w=320, var=None):
    """Editable dropdown — can pick from list OR type a custom value."""
    C = T()
    v = var or ctk.StringVar(value=values[0] if values else '')
    cb = ctk.CTkComboBox(p, values=values, variable=v, width=w, height=38,
                         fg_color=C['surface2'], border_color=C['border'],
                         button_color=C['gold'], button_hover_color=C['gold2'],
                         text_color=C['text'], font=F['body'], corner_radius=6,
                         dropdown_fg_color=C['surface2'], dropdown_text_color=C['text'],
                         state='normal')    # ← allows typing custom values
    return cb, v

