def load_kings_logo(size=(80,80)):
    """Load the Kings School logo from embedded base64."""
    try:
        import base64, io
        from PIL import Image as PILImage, ImageTk
        data = base64.b64decode(KINGS_LOGO_B64)
        pil = PILImage.open(io.BytesIO(data)).convert('RGBA')
        pil = pil.resize(size, PILImage.LANCZOS)
        return ImageTk.PhotoImage(pil)
    except Exception as e:
        print(f"Logo load error: {e}")
        return None

_kings_logo_cache = {}
def get_logo(size=(80,80)):
    key = str(size)
    if key not in _kings_logo_cache:
        img = load_kings_logo(size)
        if img: _kings_logo_cache[key] = img
    return _kings_logo_cache.get(key)

