    def _do_login(self):
        u = self._lu.get().strip(); p = self._lp.get().strip()
        rows = qy("SELECT Role, FullName, Username FROM Users WHERE (Username=? OR Email=?) AND PasswordHash=?", (u,u,p))
        if rows:
            self.current_role = rows[0][0]
            self.current_user = rows[0][1] or rows[0][2]
            self.current_username = rows[0][2]
            try: ex("UPDATE Users SET LastLogin=GETDATE() WHERE Username=?", (rows[0][2],))
            except: pass
