    def _emp_bulk_upload(self, reload_fn):
        """Bulk upload employees from Excel."""
        path = filedialog.askopenfilename(
            title='Select Employee Bulk Upload Excel',
            filetypes=[('Excel','*.xlsx *.xls')], parent=self)
        if not path: return
        try:
            import openpyxl, re
            wb = openpyxl.load_workbook(path, data_only=True)
            ws = wb.active
            rows = list(ws.iter_rows(values_only=True))
            if len(rows) < 2:
                messagebox.showerror('Error','Excel has no data rows.',parent=self); return

            # Row 1 = field keys, Row 2 = human labels, Row 3+ = data
            if len(rows) < 3:
                messagebox.showerror('Error','Excel has no data rows.',parent=self); return

            # Map field key → column index using Row 1
            header = [str(c).strip() if c else '' for c in rows[0]]
            col_map = {}
            for fi, field in enumerate(self.EMP_ALL_FIELDS):
                for hi, h in enumerate(header):
                    if h == field:
                        col_map[field] = hi; break

            added = 0; skipped = []; errors = []

            for row_idx, row in enumerate(rows[2:], start=3):  # start from row 3
                if not row or all(c is None for c in row): continue
                cells = [str(c).strip() if c is not None else '' for c in row]

                vals = {}
                for field, ci in col_map.items():
                    vals[field] = cells[ci] if ci < len(cells) and cells[ci] else None

                # ── Check required fields ──
                row_errors = []
                for field in self.EMP_REQUIRED:
                    if not vals.get(field):
                        row_errors.append(field)

                if row_errors:
                    name = vals.get('FirstName','') or f'Row {row_idx}'
                    errors.append(f"Row {row_idx} ({name}): Missing required — {', '.join(row_errors[:3])}{'...' if len(row_errors)>3 else ''}")
                    skipped.append(row_idx); continue

                # ── Date validation ──
                date_fields = ['DateOfBirth','DateOfJoining','ContractStartDate',
                               'ContractEndDate','ConfirmationDate','InsuranceStartDate','EffectiveFromDate']
                date_error = False
                for df in date_fields:
                    v = vals.get(df)
                    if not v: continue
                    if not re.match(r'^\d{4}-\d{2}-\d{2}$', v):
                        errors.append(f"Row {row_idx}: {df} must be YYYY-MM-DD, got '{v}'")
                        date_error = True; break
                if date_error:
                    skipped.append(row_idx); continue

                # ── Duplicate check ──
                dup_fields = [('NationalID','National ID'),
                              ('MobileNumber','Mobile'),('PersonalEmail','Email')]
                dup_found = False
                for df, dlabel in dup_fields:
                    v = vals.get(df)
                    if not v: continue
                    if qy(f"SELECT EmpID FROM Employees WHERE {df}=?", (v,)):
                        errors.append(f"Row {row_idx}: {dlabel} '{v}' already exists in system")
                        dup_found = True; break
                if dup_found:
                    skipped.append(row_idx); continue

                # ── Auto-generate Employee ID ──
                try:
                    last = qy("SELECT TOP 1 EmployeeID FROM Employees WHERE EmployeeID LIKE 'EMP-%' ORDER BY EmpID DESC")
                    if last and last[0][0]:
                        num = int(last[0][0].replace('EMP-','').strip()) + 1
                    else:
                        num = 1
                    vals['EmployeeID'] = f"EMP-{num:03d}"
                except:
                    vals['EmployeeID'] = f"EMP-{row_idx:03d}"

                # ── Handle IsTaxable ──
                if vals.get('IsTaxable'):
                    vals['IsTaxable'] = '1' if vals['IsTaxable'].lower() in ('yes','1','true') else '0'

                # ── Insert ──
                try:
                    valid_cols = []
                    valid_vals = []
                    # Include auto-generated EmployeeID first
                    valid_cols.append('EmployeeID')
                    valid_vals.append(vals['EmployeeID'])
                    # Then all other fields
                    for k in self.EMP_ALL_FIELDS:
                        v = vals.get(k)
                        if v is not None and str(v).strip() != '':
                            valid_cols.append(k)
                            valid_vals.append(str(v).strip())
                    assert len(valid_cols) == len(valid_vals)
                    sql = f"INSERT INTO Employees({','.join(valid_cols)}) VALUES({','.join('?' for _ in valid_cols)})"
                    ex(sql, tuple(valid_vals))
                    added += 1
                except Exception as e:
                    errors.append(f"Row {row_idx}: DB error — {str(e)[:60]}")
                    skipped.append(row_idx)

            # ── Results ──
            msg = f'✅ {added} employee(s) added successfully.'
            if skipped:
                msg += f'\n⚠ {len(skipped)} row(s) skipped.'
            if errors:
                msg += '\n\nDetails:\n' + '\n'.join(errors[:10])
                if len(errors) > 10: msg += f'\n... and {len(errors)-10} more'
            messagebox.showinfo('Bulk Upload Complete', msg, parent=self)
            reload_fn()

        except Exception as e:
            messagebox.showerror('Error', str(e), parent=self)

    def _emp_delete(self, reload_fn):
        eid = self._emp_selected()
        if not eid: messagebox.showinfo('Select', 'Click an employee row first.', parent=self); return
        if messagebox.askyesno('Delete', 'Delete this employee record? This cannot be undone.', parent=self):
            ex("DELETE FROM Employees WHERE EmpID=?", (eid,)); reload_fn()

    def _emp_edit(self, reload_fn):
        eid = self._emp_selected()
        if not eid: messagebox.showinfo('Select', 'Click an employee row first.', parent=self); return
        self._emp_form(reload_fn, edit_id=eid)

    # ── Employee Form (8 tabs) ───────────────────────────────
    def _emp_form(self, reload_fn, edit_id=None):
        C = T()
        existing = {}
        if edit_id:
            r = qy("SELECT * FROM Employees WHERE EmpID=?", (edit_id,))
            if r:
                try:
                    cols = [d[0] for d in qy("SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='Employees' ORDER BY ORDINAL_POSITION")]
                    existing = dict(zip(cols, r[0]))
                except: pass

        w = ctk.CTkToplevel(self)
        w.title('Edit Employee' if edit_id else 'Add Employee')
        w.geometry('880x760'); w.configure(fg_color=C['surface']); w.grab_set(); w.after(60, w.lift)
        ctk.CTkFrame(w, height=3, fg_color=C['gold']).pack(fill='x')
        L(w, 'Edit Employee' if edit_id else 'New Employee', C['text'], 'h2').pack(pady=(12,2))

        # ── Field type definitions ───────────────────────────
        DATE_FIELDS   = {'DateOfBirth','DateOfJoining','ContractStartDate','ContractEndDate',
                         'ConfirmationDate','InsuranceStartDate','EffectiveFromDate'}
        NUM_FIELDS    = {'BasicSalary','GrossSalary','BasicInsuranceSalary','HousingAllowance',
                         'TransportAllowance','OtherFixedAllowances','VariableAllowances',
                         'Overtime','Bonuses','Commissions','OtherEarnings','RecurringDeductions',
                         'OtherTaxExemptions','InsuranceWage','ReImbursement','FlightAllowance','ReAllocationAllowance'}
        TEXT_ONLY     = {'FirstName','SecondName','ThirdName','FamilyName','FullNameArabic',
                         'JobTitle','Department','Branch','ReportingManager','InsuranceOffice',
                         'PreviousEmployer','BankName'}
        NUM_ONLY      = {'NationalID','MobileNumber'}
        EMAIL_FIELDS  = {'PersonalEmail'}
        UNIQUE_FIELDS = {'NationalID','EmployeeID','InsuranceNumber',
                         'TaxRegistrationID','BankAccountNumber','IBAN','PersonalEmail','MobileNumber'}

        fields = {}

        def gv(key):
            v = existing.get(key)
            return str(v) if v is not None and str(v).strip() and str(v) != 'None' else ''

        def make_entry(parent, key, placeholder='', w_=360):
            if key in DATE_FIELDS:
                var = ctk.StringVar(value=gv(key))
                fr = ctk.CTkFrame(parent, fg_color='transparent')
                e = ctk.CTkEntry(fr, textvariable=var, placeholder_text='YYYY-MM-DD',
                                  width=w_, height=38, fg_color=C['surface2'],
                                  border_color=C['border'], text_color=C['text'],
                                  placeholder_text_color=C['text4'], font=F['body'],
                                  corner_radius=6, border_width=1)
                el = ctk.CTkLabel(fr, text='', text_color='#E87060', font=F['tiny'])
                def _vd(*_, v=var, e=e, el=el):
                    import re; val=v.get()
                    if not val: e.configure(border_color=C['border']); el.configure(text=''); return
                    if re.match(r'^\d{4}-\d{2}-\d{2}$', val):
                        try:
                            datetime.strptime(val,'%Y-%m-%d')
                            e.configure(border_color='#4ECCA3'); el.configure(text='✓',text_color='#4ECCA3'); return
                        except: pass
                    e.configure(border_color='#E87060')
                    el.configure(text='⚠ YYYY-MM-DD e.g. 2024-01-31',text_color='#E87060')
                var.trace_add('write',_vd)
                e.pack(side='left'); el.pack(side='left',padx=6)
                e.get=lambda:var.get(); e.insert=lambda i,v:var.set(v); e._frame=fr
                return e

            elif key in NUM_FIELDS or key in NUM_ONLY:
                var = ctk.StringVar(value=gv(key))
                e = ctk.CTkEntry(parent, textvariable=var, placeholder_text=placeholder or ('0' if key in NUM_ONLY else '0.00'),
                                  width=w_, height=38, fg_color=C['surface2'],
                                  border_color=C['border'], text_color=C['text'],
                                  placeholder_text_color=C['text4'], font=F['body'],
                                  corner_radius=6, border_width=1)
                def _vn(*_, v=var, nf=(key in NUM_FIELDS)):
                    raw=v.get()
                    if nf: clean=''.join(c for c in raw if c.isdigit() or c=='.')
                    else:  clean=''.join(c for c in raw if c.isdigit())
                    if clean.count('.')>1: clean=clean[:clean.rfind('.')]
                    if clean!=raw: v.set(clean)
                var.trace_add('write',_vn)
                return e

            elif key in EMAIL_FIELDS:
                var = ctk.StringVar(value=gv(key))
                e = ctk.CTkEntry(parent, textvariable=var, placeholder_text='name@domain.com',
                                  width=w_, height=38, fg_color=C['surface2'],
                                  border_color=C['border'], text_color=C['text'],
                                  placeholder_text_color=C['text4'], font=F['body'],
                                  corner_radius=6, border_width=1)
                def _ve(*_, v=var, e=e):
                    import re; val=v.get()
                    if not val: e.configure(border_color=C['border']); return
                    if re.match(r'^[^@]+@[^@]+\.[^@]+$', val):
                        e.configure(border_color='#4ECCA3')
                    else:
                        e.configure(border_color='#E87060')
                var.trace_add('write',_ve)
                return e

            elif key in TEXT_ONLY:
                var = ctk.StringVar(value=gv(key))
                e = ctk.CTkEntry(parent, textvariable=var, placeholder_text=placeholder,
                                  width=w_, height=38, fg_color=C['surface2'],
                                  border_color=C['border'], text_color=C['text'],
                                  placeholder_text_color=C['text4'], font=F['body'],
                                  corner_radius=6, border_width=1)
                def _vt(*_, v=var):
                    raw=v.get()
                    clean=''.join(c for c in raw if not c.isdigit())
                    if clean!=raw: v.set(clean)
                var.trace_add('write',_vt)
                return e

            else:
                val=gv(key)
                e=ctk.CTkEntry(parent, placeholder_text=placeholder, width=w_, height=38,
                               fg_color=C['surface2'], border_color=C['border'],
                               text_color=C['text'], placeholder_text_color=C['text4'],
                               font=F['body'], corner_radius=6, border_width=1)
                if val: e.insert(0,val)
                return e

