    def _it_assign_dlg(self, reload_fn):
        C = T()
        w = ctk.CTkToplevel(self); w.title('Assign Device')
        w.geometry('480x420'); w.configure(fg_color=C['surface']); w.grab_set(); w.after(60,w.lift)
        ctk.CTkFrame(w,height=3,fg_color=C['gold']).pack(fill='x')
        L(w,'Assign Device',C['text'],'h2').pack(pady=(16,8))
        fm = ctk.CTkFrame(w,fg_color=C['surface']); fm.pack(fill='x',padx=28)
        assets = qy("SELECT AssetID,Name,ISNULL(Model,'') FROM ITAssets ORDER BY Name")
        a_opts=[f"{r[1]} ({r[2]}) #{r[0]}" for r in assets]
        a_map={f"{r[1]} ({r[2]}) #{r[0]}":(r[0],f"{r[1]}") for r in assets}
        emps = qy("SELECT EmpID,ISNULL(FirstName,'')+' '+ISNULL(FamilyName,''),ISNULL(JobTitle,'') FROM Employees ORDER BY FirstName")
        e_opts=[f"{r[1].strip()} — {r[2]}" for r in emps]
        e_map={f"{r[1].strip()} — {r[2]}":r[1].strip() for r in emps}
        caps_lbl(fm,'Device').pack(anchor='w',pady=(8,2))
        av=ctk.StringVar(value=a_opts[0] if a_opts else '')
        acb,_=dropdown(fm,a_opts,w=420,var=av); acb.pack()
        caps_lbl(fm,'Assign To (Employee)').pack(anchor='w',pady=(12,2))
        ev=ctk.StringVar(value=e_opts[0] if e_opts else '')
        ecb,_=dropdown(fm,e_opts,w=420,var=ev); ecb.pack()
        caps_lbl(fm,'Due Date (optional)').pack(anchor='w',pady=(12,2))
        due=inp(fm,w=420,placeholder='YYYY-MM-DD'); due.pack()
        caps_lbl(fm,'Notes (optional)').pack(anchor='w',pady=(12,2))
        notes=inp(fm,w=420); notes.pack()
        def save():
            try:
                if not a_opts: raise ValueError('No assets available.')
                aid, alabel = a_map[av.get()]
                who = e_map.get(ev.get(), ev.get())
                ex("INSERT INTO ITAssignments(AssetID,AssetLabel,AssignedTo,AssignedBy,DueDate,Status,Notes) VALUES(?,?,?,?,?,'Assigned',?)",
                   (aid,alabel,who,self.current_user,due.get().strip(),notes.get().strip()))
                reload_fn(); w.destroy()
            except Exception as e: messagebox.showerror('Error',str(e),parent=w)
        blue_btn(w,'Assign Device',save,w=420,h=42).pack(pady=14,padx=28)

